   <body>
     <div id="app"></div>
     <script>
       const state = {
         isDeleted: false,
       };

       function Header() {
         return `
           <header class="page-shell">
             <div class="hero">
               <div>
                 <p class="eyebrow">Library preview</p>
                 <h1>Image preview</h1>
                 <p>Review the image details and confirm destructive actions before removing anything from your library.</p>
               </div>
             </div>
           </header>
         `;
       }

       function PreviewCard() {
         if (state.isDeleted) {
           return `
             <section class="card preview-card" aria-labelledby="image-heading">
               <div class="content">
                 <h2 id="image-heading">Selected image</h2>
                 <div class="deleted-state">
                   <div>
                     <p class="eyebrow">Removed</p>
                     <p>The image has been deleted from your library.</p>
                   </div>
                 </div>
               </div>
             </section>
           `;
         }

         return `
           <section class="card preview-card" aria-labelledby="image-heading">
             <div class="preview-frame" role="img" aria-label="Mountain valley during sunrise with a lake in the foreground"></div>
             <div class="content">
               <h2 id="image-heading">Selected image</h2>
               <p class="meta">A landscape capture prepared for the autumn collection.</p>
               <dl class="info-list">
                 <div class="info-item">
                   <dt>Resolution</dt>
                   <dd>3840 x 2400</dd>
                 </div>
                 <div class="info-item">
                   <dt>Format</dt>
                   <dd>JPEG</dd>
                 </div>
                 <div class="info-item">
                   <dt>Size</dt>
                   <dd>7.8 MB</dd>
                 </div>
               </dl>
               <div class="button-row">
                 <button type="button" class="trigger" data-open-dialog>
                   Delete image
                 </button>
                 <button type="button" class="secondary">
                   Download original
                 </button>
               </div>
             </div>
           </section>
         `;
       }

       function DetailsPanel() {
         return `
           <aside class="card side-panel" aria-labelledby="details-heading">
             <h2 id="details-heading">Library details</h2>
             <p>Use delete only when the asset is no longer needed in any collection. This action removes it from your library.</p>
             <p class="status" aria-live="polite" data-tone="${state.isDeleted ? "success" : "default"}">
               ${state.isDeleted ? "Image deleted from your library." : ""}
             </p>
           </aside>
         `;
       }

       function DeleteDialog() {
         return `
           <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
             <div class="dialog-body">
               <h2 id="delete-dialog-title" class="dialog-title">Delete this image?</h2>
               <p id="delete-dialog-description" class="dialog-copy">
                 This image will be removed from your library. You can press Cancel to keep it, or Delete to confirm the removal.
               </p>
               <div class="dialog-actions">
                 <button type="button" class="secondary" data-close-dialog autofocus>Cancel</button>
                 <button type="button" class="danger" data-confirm-delete>Delete image</button>
               </div>
             </div>
           </dialog>
         `;
       }

       function App() {
         return `
           <a class="skip-link" href="#maincontent">Skip to main content</a>
           ${Header()}
           <main id="maincontent" class="page-shell" tabindex="-1">
             <div class="layout">
               ${PreviewCard()}
               ${DetailsPanel()}
             </div>
           </main>
           ${DeleteDialog()}
         `;
       }

       function render() {
         const root = document.getElementById("app");
         root.innerHTML = App();

         const dialog = document.getElementById("delete-dialog");
         const openButton = document.querySelector("[data-open-dialog]");
         const closeButton = document.querySelector("[data-close-dialog]");
         const confirmButton = document.querySelector("[data-confirm-delete]");

         if (openButton) {
           openButton.addEventListener("click", () => dialog.showModal());
         }

         closeButton.addEventListener("click", () => dialog.close("cancel"));

         confirmButton.addEventListener("click", () => {
           state.isDeleted = true;
           dialog.close("delete");
           render();
         });
       }

       render();
     </script>
   </body>
 </html>

