             </div>
           </header>
         `;
       }

       function PreviewCard() {
         if (state.isDeleted) {
           return `
             <section class="card preview-card" aria-labelledby="image-heading">
               <div class="content">
                 <h2 id="image-heading" tabindex="-1">Selected image</h2>
                 <div class="deleted-state">
                   <div>
                     <p class="eyebrow">Removed</p>
                     <p>The image has been deleted from your library.</p>
                   </div>
                 </div>
               </div>
             </section>
           `;
         }

         return `
           <section class="card preview-card" aria-labelledby="image-heading">
             <div class="preview-frame" role="img" aria-label="Mountain valley during sunrise with a lake in the foreground"></div>
             <div class="content">
               <h2 id="image-heading">Selected image</h2>
               <p class="meta">A landscape capture prepared for the autumn collection.</p>
               <dl class="info-list">
                 <div class="info-item">
                   <dt>Resolution</dt>
                   <dd>3840 x 2400</dd>
                 </div>
                 <div class="info-item">
                   <dt>Format</dt>
                   <dd>JPEG</dd>
                 </div>
                 <div class="info-item">
                   <dt>Size</dt>
                   <dd>7.8 MB</dd>
                 </div>
               </dl>
               <div class="button-row">
                 <button type="button" class="trigger" data-open-dialog>
                   Delete image
                 </button>
                 <button type="button" class="secondary">
                   Download original
                 </button>
               </div>
             </div>
           </section>
         `;
       }

       function DetailsPanel() {
         return `
           <aside class="card side-panel" aria-labelledby="details-heading">
             <h2 id="details-heading">Library details</h2>
             <p>Use delete only when the asset is no longer needed in any collection. This action removes it from your library.</p>
             <p class="status" aria-live="polite" data-tone="${state.isDeleted ? "success" : "default"}">
               ${state.isDeleted ? "Image deleted from your library." : ""}
             </p>
           </aside>
         `;
       }

       function DeleteDialog() {
         return `
           <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
             <div class="dialog-body">
               <h2 id="delete-dialog-title" class="dialog-title">Delete this image?</h2>
               <p id="delete-dialog-description" class="dialog-copy">
