               <div class="dialog-actions">
                 <button type="button" class="secondary" data-close-dialog autofocus>Cancel</button>
                 <button type="button" class="danger" data-confirm-delete>Delete image</button>
               </div>
             </div>
           </dialog>
         `;
       }

